import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {execFileSync,spawnSync} from 'node:child_process';
import {createRequire,default as Module} from 'node:module';
import {resolve,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {cpus,release} from 'node:os';
const root=process.cwd(), self=fileURLToPath(import.meta.url), hash=x=>createHash('sha256').update(x).digest('hex');
const source=readFileSync(resolve(root,'src/core/policy.ts'),'utf8'), sourceHash=hash(source);
const require=createRequire(resolve(root,'package.json')), ts=require('typescript');
const ast=ts.createSourceFile('policy.ts',source,ts.ScriptTarget.Latest,true), literals=[];
function visit(n){if(n.kind===ts.SyntaxKind.RegularExpressionLiteral)literals.push({line:ast.getLineAndCharacterOfPosition(n.getStart()).line+1,literal:n.getText(ast)});ts.forEachChild(n,visit);}visit(ast);
if(literals.length!==51)throw Error('inventory drift');
const helpers=['containsShellCommand','containsTechnicalTokenShape','hasTechnicalTokenShape','hasCommandArgumentShape','isShellCommandLine','looksLikeCommandOrAssignment','stripShellPunctuation','isPositiveSemanticText','isPositiveSemanticLine'];
const extra=`\nexports.probe={EXACT_PATTERNS,classifyContext,${helpers.join(',')},literals:[${literals.map(x=>x.literal).join(',')}]};`;
const mod=new Module(resolve(root,'src/core/policy.ts'));mod.filename=resolve(root,'src/core/policy.ts');mod.paths=Module._nodeModulePaths(root);
mod._compile(ts.transpileModule(source+extra,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,mod.filename);
const api=mod.exports.probe, recipes=[], assignments=[];
// Explicit syntactic repetition slots, with minimal enabling prefix and both tails.
function add(line,slot,prefix,unit,matchTail,boundaryTail,paths=[]){
 const id=`L${line}-${slot}`; recipes.push({id,line,slot,prefix,unit,matchTail,boundaryTail});
 for(const target of [`regex:${line}`,...paths]) assignments.push({target,recipe:id});
}
add(436,'gap','token',' ',':','!', ['exact:0']);
for(const [slot,p,u,g,b] of [['auth-gap','Authorization',' ',':Bearer A','!Bearer A'],['colon-gap','Authorization:',' ','Bearer A','!Bearer A'],['bearer-gap','Authorization:Bearer',' ','A','!'],['token','Authorization:Bearer ','A','','!']])add(437,slot,p,u,g,b,['exact:1']);
add(438,'gap','Bearer',' ','AAAAAAAA','!', ['exact:2']);
add(438,'token','Bearer ','A','','!', ['exact:2','classifyContext']);
add(440,'key-body','-----BEGIN ','A','PRIVATE KEY-----','PRIVATE KEY----!', ['exact:4']);
add(441,'root-segment','/','a','/','!', ['exact:5']);
add(441,'tail','C:/','x','',' ', ['exact:5']);
add(444,'first-segment','','a','/a','?',['exact:8']);
add(444,'next-segment','a/','a','','?',['exact:8']);
add(444,'segment-group','a','/a','','?',['exact:8']);
add(446,'indent','',' ','npm','nmp',['exact:10']);
add(446,'sudo-gap','sudo',' ','npm','nmp',['exact:10']);
for(const line of [447,551]){
 const paths=line===447?['exact:11']:['hasTechnicalTokenShape','containsTechnicalTokenShape'];
 add(line,'verb-gap','run',' ','x','!',paths);
 add(line,'command-rest','run a','a','','!',paths);
 add(line,'argument-gap','run x',' ','a','!',paths);
 add(line,'argument-token','run x ','a','','!',paths);
}
add(448,'indent','',' ','const','consx',['exact:12']);
add(260,'tag-name','<a','a','>','!', ['exact:18']);
add(260,'attributes','<a ','x','>','<', ['exact:18']);
for(const [line,key,paths] of [[455,'id',['exact:19']],[378,'trace',['exact:21','hasTechnicalTokenShape','containsTechnicalTokenShape']]]){
 add(line,'gap1',key,' ','=aaaaaa','!',paths);
 add(line,'gap2',key+'=',' ','aaaaaa','!',paths);
 add(line,'value',key+'=','a','','!', [...paths,'classifyContext']);
 add(line,'value-word-miss',key+'=','a','','g',paths);
 add(line,'value-dots',key+'=','.', 'a','!', paths);
}
for(const line of [458,554]){
 const paths=line===458?['exact:22']:['hasTechnicalTokenShape','containsTechnicalTokenShape'];
 add(line,'left-rest','a','a','_a','!',paths);
 add(line,'right-token','a_','a','','!',paths);
}
add(459,'hex','','a','','g',['exact:23','classifyContext']);
add(460,'left','','A','-AAA','!', ['exact:24']);
add(460,'right','AA-','A','','g', ['exact:24']);
add(462,'integer','','1','','a',['exact:26']);
add(462,'fraction','1.','1','','a',['exact:26']);
for(const [slot,p,u,g,b] of [['permission-who','','u','+r','!'],['permission-mode','u+','r','','!'],['option-rest','--a','a','','!'],['assignment-rest','A','A','=a','=!'],['path-rest','a','a','/x','/!']])add(558,slot,p,u,g,b,['hasCommandArgumentShape']);
add(597,'split-space','npm',' ','test','!', ['isShellCommandLine','containsShellCommand']);
for(const line of [624,633,646]){
 const paths=line===646?['looksLikeCommandOrAssignment']:['isShellCommandLine','containsShellCommand'];
 add(line,'assignment-name','A','A','=x','=!',paths);
 add(line,'assignment-value','A=','x','','\n',paths);
}
add(536,'word-rest','a','a','','!', ['isPositiveSemanticLine','isPositiveSemanticText']);
add(543,'upper-run','','A','','a', ['isPositiveSemanticLine']);
// Non-regex scanners still receive minimal enabling prefixes and both endings.
function scan(id,p,u,g,b,paths){const r={id,line:null,slot:'scanner-control',prefix:p,unit:u,matchTail:g,boundaryTail:b};recipes.push(r);for(const target of paths)assignments.push({target,recipe:id});}
scan('uri','a','a',':','!',['exact:3']);scan('dotted','a','a','.ts','.!',['exact:6']);scan('filename','a','a','.ts','.tsx!',['exact:7']);
scan('sql','SELECT ',' ','FROM','FROX',['exact:13']);scan('delimiter','{','a','=','!',['exact:14']);
scan('bang','<!A','a','>','!',['exact:15']);scan('php','<?a','a','?>','?!',['exact:16']);scan('comment','<!--','a','-->','--!',['exact:17']);
scan('identifier','a-id=','a','','!', ['exact:20']);scan('table','|','a','|','!', ['exact:25']);
scan('strip','(','(',')','!', ['stripShellPunctuation']);
// Bounded/constant literals have no unbounded slot. Stress the surrounding scan
// with neutral padding; this is not a claim that a one-code-point predicate matches a whole large string.
const boundedExamples={36:'SELECT',37:'FROM',38:'<?a',143:'a',144:'a',221:'{',264:'a',287:'a',291:'a',295:'a',335:'i',338:'d',374:' ',445:'error',488:'visual',522:'\n',534:'a',541:'.',542:'{',565:'a',571:' ',575:' ',589:'\n',593:'\n',652:'(',653:')'};
for(const l of literals){if(recipes.some(r=>r.line===l.line))continue; const token=boundedExamples[l.line];if(token===undefined)throw Error('unmapped literal '+l.line);add(l.line,'bounded-control','','!',token,'x',l.line===445?['exact:9']:l.line===488?['visual']:[]);}
// COMMAND_ARGUMENT_SUFFIX is sticky; its direct invocation starts at0, whereas
// its actual helper needs a command prefix. Record that adapter explicitly.
for(const a of assignments)if(a.target==='hasCommandArgumentShape'&&a.recipe.startsWith('L558-'))a.inputPrefix='x ';
const unique=new Set(assignments.map(a=>a.target+'|'+a.recipe));if(unique.size!==assignments.length)throw Error('duplicate assignment');
const sizes=[6000000,10485760,20971520],endings=['match','boundary-failure'];
function inputFor(r,n,ending,adapter=''){const p=adapter+r.prefix,s=ending==='match'?r.matchTail:r.boundaryTail;const room=n-p.length-s.length;if(room<0)throw Error('input too short');const units=Math.floor(room/r.unit.length),rest=room%r.unit.length;return ' '.repeat(rest)+p+r.unit.repeat(units)+s;}
function invoke(target,input){let f;if(target.startsWith('regex:'))f=api.literals[literals.findIndex(l=>l.line===Number(target.slice(6)))];else if(target.startsWith('exact:'))f=api.EXACT_PATTERNS[Number(target.slice(6))][1];else if(target==='visual')f=api.literals[literals.findIndex(l=>l.line===488)];else f=api[target];if(f instanceof RegExp)f.lastIndex=0;const value=typeof f==='function'?f(input):f.test(input);return typeof value==='string'?{stringLength:value.length}:value;}
function child(){const [idx,ending,sizeText,expectedHash]=process.argv.slice(3),a=assignments[Number(idx)],r=recipes.find(r=>r.id===a.recipe),n=Number(sizeText);if(sourceHash!==expectedHash||!endings.includes(ending)||![256,...sizes].includes(n))throw Error('child validation');const input=inputFor(r,n,ending,a.inputPrefix);console.log(JSON.stringify({record:'metadata',target:a.target,recipe:r.id,ending,size:n,utf8Bytes:Buffer.byteLength(input),utf16CodeUnits:input.length,sourceHash}));const started=process.hrtime.bigint();let out;try{out={status:'returned',value:invoke(a.target,input)}}catch(e){out={status:'threw',error:{name:e.name,message:e.message}}}console.log(JSON.stringify({record:'outcome',...out,operationElapsedNs:String(process.hrtime.bigint()-started)}));}
function sample(idx,ending,n){const a=assignments[idx],start=performance.now();const proc=spawnSync(process.execPath,[self,'--child',String(idx),ending,String(n),sourceHash],{cwd:root,windowsHide:true,timeout:20000,encoding:'utf8',maxBuffer:1024*1024});const row={...a,ending,size:n,timeoutMs:20000,wallMs:performance.now()-start,exitCode:proc.status,signal:proc.signal};const records=(proc.stdout||'').split(/\r?\n/).filter(Boolean).flatMap(s=>{try{return[JSON.parse(s)]}catch{return[]}}),m=records.find(x=>x.record==='metadata'),o=records.find(x=>x.record==='outcome');if(m)row.metadata=m;if(proc.error?.code==='ETIMEDOUT')return{...row,status:'timeout-censored'};if(proc.error||proc.status!==0||!m||!o||m.target!==a.target||m.recipe!==a.recipe||m.ending!==ending||m.size!==n||m.utf8Bytes!==n||m.utf16CodeUnits!==n||m.sourceHash!==sourceHash)return{...row,status:'infrastructure-error',error:proc.error?.message||(proc.stderr||'invalid metadata').slice(0,2000)};return{...row,...o};}
function parent(smoke){
 const inventory=literals.map(l=>({...l,recipes:recipes.filter(r=>r.line===l.line).map(r=>r.id),noUnboundedRepetition:Object.hasOwn(boundedExamples,l.line)}));
 const smokeResults=assignments.flatMap((a,idx)=>endings.map(ending=>{const r=recipes.find(r=>r.id===a.recipe),input=inputFor(r,256,ending,a.inputPrefix);if(input.length!==256||Buffer.byteLength(input)!==256)throw Error('size');return{...a,ending,value:invoke(a.target,input)};}));
 // Anchored slots without a terminal boundary legitimately retain a prefix match
 // for the boundary-failure tail; retain observed booleans instead of asserting false.
 for(const target of ['exact:2','exact:19','exact:23']){const ids={'exact:2':'L438-token','exact:19':'L455-value','exact:23':'L459-hex'};if(!smokeResults.find(x=>x.target===target&&x.recipe===ids[target]&&x.ending==='match')?.value)throw Error('positive smoke '+target);}
 if(smoke){console.log(JSON.stringify({literalCount:literals.length,recipeCount:recipes.length,assignmentCount:assignments.length,smokeCells:smokeResults.length,smokeResults}));return;}
 const measuredAt=new Date().toISOString(), report={phase:'N-01 per-regex derived planning probe; product unchanged',measuredAt,environment:{node:process.version,v8:process.versions.v8,platform:process.platform,arch:process.arch,release:release(),cpu:cpus()[0]?.model},source:{gitHead:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8',windowsHide:true}).trim(),path:'src/core/policy.ts',sha256:sourceHash,oraclePath:'tests/helpers/policy-baseline.ts',oracleSha256:hash(readFileSync(resolve(root,'tests/helpers/policy-baseline.ts')))},method:{sizes,units:'ASCII inputs: UTF8 bytes = UTF16 code units',childTimeoutMs:20000,samplesPerCell:1,sequential:true,warmup:false,coverage:'assignments x endings x sizes; explicit literal repetition slots plus wrapper paths',limits:'One sample, no performance median or equivalence proof. Boundary-failure describes appended token, not guaranteed false for unanchored/prefix matches. Bounded-control is surrounding-scan stress only.'},regexInventory:inventory,recipes,assignments,smokeResults,runner:{sha256:hash(readFileSync(self)),source:readFileSync(self,'utf8')},results:[]};
 const out=resolve(root,'docs/research/evidence/n01',`exception-probes-${measuredAt.replaceAll(':','-')}.json`);mkdirSync(dirname(out),{recursive:true});writeFileSync(out,'{}\n',{flag:'wx'});console.log(out);const save=()=>writeFileSync(out,JSON.stringify(report,null,2)+'\n');
 for(let i=0;i<assignments.length;i++)for(const ending of endings)for(const n of sizes){const row=sample(i,ending,n);report.results.push(row);save();if(row.status!=='returned'||report.results.length%50===0)console.log(JSON.stringify({done:report.results.length,total:assignments.length*6,target:row.target,recipe:row.recipe,ending,n,status:row.status,error:row.error}));}
 report.finishedAt=new Date().toISOString();report.coverage={expected:assignments.length*6,actual:report.results.length,counts:report.results.reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{})};save();console.log(JSON.stringify(report.coverage));if(report.coverage.counts['infrastructure-error'])process.exitCode=1;
}
if(process.argv[2]==='--child')child();else parent(process.argv.includes('--smoke'));
